CREATE TABLE IF NOT EXISTS questions(id VARCHAR(80) PRIMARY KEY,owner_id VARCHAR(80) NOT NULL,prompt VARCHAR(2000) NOT NULL,kind VARCHAR(20) NOT NULL,definition JSON NOT NULL,status ENUM('draft','published','disabled') NOT NULL DEFAULT 'draft',global_published BOOLEAN NOT NULL DEFAULT 0,class_id VARCHAR(80) NULL,created_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),updated_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3) ON UPDATE CURRENT_TIMESTAMP(3),INDEX(owner_id,status),FOREIGN KEY(owner_id) REFERENCES users(id));
